  if(_RES_TERRAIN_KEY.has(tid))return _RES_TERRAIN_KEY.get(tid);
  let key='';
  for(const [id,r] of RESIDUAL_EXPIRY) if(r.site==='terrain'&&terrainId(id)===tid){key=id;break;}
