        const _fsc=slotCondOf(_fsf);
        if(_fsc[_fslot]){{if(TR)TR.attrStill();mvFail(m);}continue;}
        _fsc[_fslot]={mv:a.mv,when:'futureHit',turns:+_dh.ticks||3,src:m};
        MEDSEEN.delayedHitBooked++;
