  {const _gf=TAGS.param('move',id,'groundsField');
   if(_gf)return {kind:'gravity',mv:id,turns:+_gf.turns||5};}
  if(TAGS.has('move',id,'sealsMoves'))return {kind:'status',mv:id,target};   // Encore rides the status path
